code.snippet:
body.t-paper .section-tag { background: transparent; border-style: dashed; letter-spacing: 3px; }
body.t-paper .card { border-left: 3px solid transparent; }
body.t-paper .card:hover { border-left-color: var(--accent); border-top-color: var(--border); border-right-color: var(--border); border-bottom-color: var(--border); }
body.t-paper .card.featured { border-left-color: var(--accent); }
body.t-paper .hero h1 { letter-spacing: -1px; }
body.t-paper .btn { border-radius: 3px; }
body.t-paper .fact { border-left: 3px solid var(--accent); }
body.t-paper .post { border-left: 3px solid transparent; }
body.t-paper .post:hover { border-left-color: var(--accent); }
